            "type": "diagram",
            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">HEAT MORTALITY</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The deadliest weather</text><rect x=\"80\" y=\"180\" width=\"940\" height=\"130\" rx=\"20\" fill=\"rgba(239,68,68,0.12)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"130\" y=\"225\" text-anchor=\"start\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"22\">2003 Europe</text><text x=\"130\" y=\"265\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">~70,000 excess deaths</text><text x=\"130\" y=\"295\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">France, Spain, Italy</text><rect x=\"80\" y=\"330\" width=\"940\" height=\"130\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"130\" y=\"375\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"22\">2010 Russia</text><text x=\"130\" y=\"415\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">~55,000 excess deaths</text><text x=\"130\" y=\"445\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Moscow 40°C for weeks</text><rect x=\"80\" y=\"480\" width=\"940\" height=\"130\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"130\" y=\"525\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">2021 PNW dome</text><text x=\"130\" y=\"565\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">600+ deaths, Portland 116°F</text><text x=\"130\" y=\"595\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">\"Virtually impossible\" w/o CC</text><rect x=\"80\" y=\"630\" width=\"940\" height=\"160\" rx=\"20\" fill=\"rgba(20,184,166,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"130\" y=\"685\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">WET-BULB LIMIT</text><text x=\"130\" y=\"725\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">>35°C: body cannot cool</text><text x=\"130\" y=\"765\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Bombay, Jakarta approaching</text><rect x=\"80\" y=\"810\" width=\"940\" height=\"200\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"870\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">2050 PROJECTION</text><text x=\"550\" y=\"915\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Heat deaths +250% in major cities</text><text x=\"550\" y=\"960\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Disproportionate: elderly, poor</text></svg>",
